sys_script_include.script:
var IAWUpdateCase = Class.create();
IAWUpdateCase.prototype = {
    initialize: function() {},

    btmh_update: function(sysId, responseBody) {
        var grTradeCase = new GlideRecord("x_hsb11_hsbc_mss_t_trade_case");
        grTradeCase.addQuery("sys_id", sysId);
        grTradeCase.query();
        if (grTradeCase.next() && responseBody) {

            var status = responseBody.STATUS;
            var mismatchSuggestions = responseBody.MISMATCH_SUGGESTIONS;
            var hsbcArray = [];
            var clientArray = [];
            var operationsArray = [];

			//changes added to accomodate the CR 996 for tactical solution in case IAW sends multiple mismatches - SINGLE Mismatch will work as it is
            if (status == "SUCCESS" && mismatchSuggestions.length == 1) {
                for (var i = 0; i < mismatchSuggestions.length; i++) {
                    if (mismatchSuggestions[i].SUGGESTED_ACTION == "HSBC potentially at fault") {
                        hsbcArray.push(mismatchSuggestions[i]);
                    } else if (mismatchSuggestions[i].SUGGESTED_ACTION == "Operations to investigate") {
                        operationsArray.push(mismatchSuggestions[i]);
                    } else if (mismatchSuggestions[i].SUGGESTED_ACTION == "Client at fault") {
                        clientArray.push(mismatchSuggestions[i]);
                    }
                }
                if (hsbcArray.length > 0) {
                    grTradeCase.widget_outcome = "HSBC Potentially at fault";
                    grTradeCase.iaw_widget_payload = JSON.stringify(hsbcArray);
                } else if (operationsArray.length > 0) {
                    grTradeCase.widget_outcome = "Operations to Investigate";
                    grTradeCase.iaw_widget_payload = JSON.stringify(operationsArray);
                } else if (clientArray.length > 0) {
                    grTradeCase.widget_outcome = "Client at fault";
                    grTradeCase.iaw_widget_payload = JSON.stringify(clientArray);
                }
                grTradeCase.update();
                return "SUCCESS";
            } 
			//changes added to accomodate the CR 996 for tactical solution in case IAW sends multiple mismatches - MULTIPLE Mismatches then we need to follow a new path and create a task for the MOCS team 
			else if (status == "SUCCESS" && mismatchSuggestions.length > 1) {
                grTradeCase.widget_outcome = "Ops to action outside iQube";
                grTradeCase.iaw_widget_payload = JSON.stringify(mismatchSuggestions);
                grTradeCase.update();
                return "SUCCESS";
            } 
			//changes added for MSSRBXCE-67 & 432
			else if (status == "FAILURE" && mismatchSuggestions.length == 1) {
                for (var j = 0; j < mismatchSuggestions.length; j++) {
                    if (mismatchSuggestions[j].SUGGESTED_ACTION == "Operations to investigate") 
                        operationsArray.push(mismatchSuggestions[j]);
                    else if (mismatchSuggestions[j].SUGGESTED_ACTION == "Client at fault") 
                        clientArray.push(mismatchSuggestions[j]);

                }
                if (operationsArray.length > 0) {
                    grTradeCase.widget_outcome = "Operations to Investigate";
                    grTradeCase.iaw_widget_payload = JSON.stringify(operationsArray);
                } else if (clientArray.length > 0) {
                    grTradeCase.widget_outcome = "Client at fault";
                    grTradeCase.iaw_widget_payload = JSON.stringify(clientArray);
                }
                grTradeCase.update();
                return "SUCCESS";
			}
			else {
                grTradeCase.widget_outcome = "Fail";
                grTradeCase.iaw_widget_payload = JSON.stringify(responseBody.EXCEPTION_DETAILS);

                return JSON.stringify(responseBody.EXCEPTION_DETAILS.ERROR_MSG[0]);
            }
        }

    },

    fcih_update: function(sysId, responseBody) {
        var grTradeCase = new GlideRecord("x_hsb11_hsbc_mss_t_trade_case");
        grTradeCase.addQuery("sys_id", sysId);
        grTradeCase.query();
        if (grTradeCase.next()) {

            var status = responseBody.STATUS;
            var match_status = responseBody.MATCH_STATUS;

            if (status == "SUCCESS") {
                if (match_status) {
                    grTradeCase.widget_outcome = "Match";
                } else {
                    grTradeCase.widget_outcome = "Does not Match";
                }

                grTradeCase.iaw_widget_payload = JSON.stringify(responseBody.SUBACCOUNT_DETAILS);
                grTradeCase.update();
                return "SUCCESS";
            } else {
                grTradeCase.widget_outcome = "Fail";
                grTradeCase.iaw_widget_payload = JSON.stringify(responseBody.EXCEPTION_DETAILS);
                grTradeCase.update();
                return JSON.stringify(responseBody.EXCEPTION_DETAILS);
            }
        }
    },

    cuh_update: function(sysId, responseBody) {

        var grTradeCase = new GlideRecord("x_hsb11_hsbc_mss_t_trade_case");
        grTradeCase.addQuery("sys_id", sysId);
        grTradeCase.query();
        if (grTradeCase.next()) {

            var status = responseBody.STATUS;

            if (status == "SUCCESS") {

                grTradeCase.widget_outcome = "Success";
                grTradeCase.iaw_widget_payload = JSON.stringify(responseBody.EXCEPTION_DETAILS);
                grTradeCase.update();
                return "SUCCESS";
            } else {
                grTradeCase.widget_outcome = "Fail";
                grTradeCase.iaw_widget_payload = JSON.stringify(responseBody.EXCEPTION_DETAILS);
                grTradeCase.update();
                //return JSON.stringify(responseBody.EXCEPTION_DETAILS);
                return JSON.stringify(responseBody.EXCEPTION_DETAILS.ERROR_MSG[0]);
            }
        }

    },
    almh_update: function(sysId, responseBody) {
        var grTradeCase = new GlideRecord("x_hsb11_hsbc_mss_t_trade_case");
        grTradeCase.addQuery("sys_id", sysId);
        grTradeCase.query();
        if (grTradeCase.next() && responseBody) {

            var status = responseBody.STATUS;
            var mismatchSuggestions = responseBody.MISMATCH_SUGGESTIONS;
            var hsbcArray = [];
            var clientArray = [];
            var operationsArray = [];

            if (status == "SUCCESS" && mismatchSuggestions.length == 1) {
                for (var i = 0; i < mismatchSuggestions.length; i++) {
                    if (mismatchSuggestions[i].SUGGESTED_ACTION == "HSBC potentially at fault") {
                        hsbcArray.push(mismatchSuggestions[i]);
                    } else if (mismatchSuggestions[i].SUGGESTED_ACTION == "Operations to investigate") {
                        operationsArray.push(mismatchSuggestions[i]);
                    } else if (mismatchSuggestions[i].SUGGESTED_ACTION == "Client at fault") {
                        clientArray.push(mismatchSuggestions[i]);
                    }
                }
                if (hsbcArray.length > 0) {
                    grTradeCase.widget_outcome = "HSBC Potentially at fault";
                    grTradeCase.iaw_widget_payload = JSON.stringify(hsbcArray);
                } else if (operationsArray.length > 0) {
                    grTradeCase.widget_outcome = "Operations to Investigate";
                    grTradeCase.iaw_widget_payload = JSON.stringify(operationsArray);
                } else if (clientArray.length > 0) {
                    grTradeCase.widget_outcome = "Client at fault";
                    grTradeCase.iaw_widget_payload = JSON.stringify(clientArray);
                }
                grTradeCase.update();
                return "SUCCESS";
            } 

		else if (status == "SUCCESS" && mismatchSuggestions.length > 1) {
                grTradeCase.widget_outcome = "Ops to action outside iQube";
                grTradeCase.iaw_widget_payload = JSON.stringify(mismatchSuggestions);
                grTradeCase.update();
                return "SUCCESS";
            }
		//changes added for MSSRBXCE-67 & 432
			else if (status == "FAILURE" && mismatchSuggestions.length == 1) {
                for (var j = 0; j < mismatchSuggestions.length; j++) {
                    if (mismatchSuggestions[j].SUGGESTED_ACTION == "Operations to investigate") 
                        operationsArray.push(mismatchSuggestions[j]);
                    else if (mismatchSuggestions[j].SUGGESTED_ACTION == "Client at fault") 
                        clientArray.push(mismatchSuggestions[j]);

                }
                if (operationsArray.length > 0) {
                    grTradeCase.widget_outcome = "Operations to Investigate";
                    grTradeCase.iaw_widget_payload = JSON.stringify(operationsArray);
                } else if (clientArray.length > 0) {
                    grTradeCase.widget_outcome = "Client at fault";
                    grTradeCase.iaw_widget_payload = JSON.stringify(clientArray);
                }
                grTradeCase.update();
                return "SUCCESS";
			}	
			else {
                grTradeCase.widget_outcome = "Fail";
                grTradeCase.iaw_widget_payload = JSON.stringify(responseBody.EXCEPTION_DETAILS);
                grTradeCase.update();
                return JSON.stringify(responseBody.EXCEPTION_DETAILS.ERROR_MSG);
            }
        }

    },
    maih_update: function(sysId, responseBody, responseCode) {
        var grTradeCase = new GlideRecord("x_hsb11_hsbc_mss_t_trade_case");
        grTradeCase.addQuery("sys_id", sysId);
        grTradeCase.query();
        if (grTradeCase.next() && responseCode) {

			//get the MAIH Outcome Mapping from the system property
			var outcomeMapping = JSON.parse(gs.getProperty('x_hsb11_iaw_widget.manual_handler_error_code_map'));

			//loop through outcomeMapping to get the IAW Response from responseCode
			for (let i = 0; i < outcomeMapping.length; i++ ) {
				if (outcomeMapping[i].ERROR_CODE == responseCode) {
					var widgetOutcome = outcomeMapping[i].IAW_OUTCOME;
				}
			}

			//if we match the Response Code and get an Outcome, then we set that and pass the Response Body to the IAW Payload field
			if (widgetOutcome) {

                grTradeCase.widget_outcome = widgetOutcome;
				grTradeCase.iaw_widget_payload = JSON.stringify(responseBody);
				grTradeCase.update();
                return widgetOutcome.toString();
            } else {
                //If we don't get a widget outcome then we need to trigger the exception process by returning Error
                grTradeCase.widget_outcome = "Fail";
                grTradeCase.iaw_widget_payload = JSON.stringify(responseBody.EXCEPTION_DETAILS);
                grTradeCase.update();
                return "ERROR";
            }
        }

    },
    error_update: function(sysId, responseBody) {
        var grTradeCase = new GlideRecord("x_hsb11_hsbc_mss_t_trade_case");
        grTradeCase.addQuery("sys_id", sysId);
        grTradeCase.query();
        if (grTradeCase.next() && responseBody) {

            grTradeCase.widget_outcome = 'Fail';
			grTradeCase.iaw_widget_payload = JSON.stringify(responseBody);
            grTradeCase.update();
            return "ERROR";
        }
    },

    type: 'IAWUpdateCase'
};
